from typing import Callable, Dict, List, Optional


def _handle_a(item: Dict) -> Optional[Dict]:
    value = item["value"] * 2
    category = "high" if value > 100 else "low"
    return {"id": item["id"], "value": value, "category": category}


def _handle_b(item: Dict) -> Optional[Dict]:
    value = item["value"] + 50
    return {"id": item["id"], "value": value, "category": "adjusted"}


def _handle_c(item: Dict) -> Optional[Dict]:
    if item["value"] < 0:
        return {"id": item["id"], "value": 0, "category": "clamped"}
    return {"id": item["id"], "value": item["value"], "category": "passthrough"}


_HANDLERS: Dict[str, Callable[[Dict], Optional[Dict]]] = {
    "A": _handle_a,
    "B": _handle_b,
    "C": _handle_c,
}


def _dispatch(item: Dict) -> Optional[Dict]:
    handler = _HANDLERS.get(item.get("type", ""))
    if handler is None:
        return None
    return handler(item)


def process_data(data: List[Dict]) -> List[Dict]:
    results = []
    for item in data:
        result = _dispatch(item)
        if result is not None:
            results.append(result)
    return results
