interface Preferences {
  theme: string;
  notifications: boolean;
  language: string;
}

interface User {
  id: number;
  name: string;
  email: string;
  preferences: Preferences;
  tags: string[];
  last_login: string; // ISO 8601, e.g. "2024-01-15T10:30:00Z"
  metadata: Record<string, unknown> | null;
}

function validateUser(user: unknown): asserts user is User {
  if (typeof user !== "object" || user === null) {
    throw new TypeError("user must be a non-null object");
  }

  const u = user as Record<string, unknown>;

  // id
  if (!Number.isInteger(u.id)) {
    throw new TypeError(`id: expected integer, got ${typeof u.id}`);
  }

  // name (non-empty string)
  if (typeof u.name !== "string" || u.name.length === 0) {
    throw new TypeError("name: expected non-empty string");
  }

  // email (must contain "@")
  if (typeof u.email !== "string" || !u.email.includes("@")) {
    throw new TypeError("email: expected string containing '@'");
  }

  // preferences
  const prefs = u.preferences;
  if (typeof prefs !== "object" || prefs === null) {
    throw new TypeError("preferences: expected object");
  }
  const p = prefs as Record<string, unknown>;
  if (typeof p.theme !== "string") {
    throw new TypeError("preferences.theme: expected string");
  }
  if (typeof p.notifications !== "boolean") {
    throw new TypeError("preferences.notifications: expected boolean");
  }
  if (typeof p.language !== "string") {
    throw new TypeError("preferences.language: expected string");
  }

  // tags (array of strings)
  if (!Array.isArray(u.tags) || !u.tags.every((t): t is string => typeof t === "string")) {
    throw new TypeError("tags: expected array of strings");
  }

  // last_login (valid ISO date string)
  if (typeof u.last_login !== "string" || Number.isNaN(Date.parse(u.last_login))) {
    throw new TypeError("last_login: expected valid ISO 8601 date string");
  }

  // metadata (null or plain object)
  if (u.metadata !== null && (typeof u.metadata !== "object" || Array.isArray(u.metadata))) {
    throw new TypeError("metadata: expected null or plain object");
  }
}
```

Notes on the choices:

- **`metadata`** is typed `Record<string, unknown> | null` because the example shows it as `None` and no shape is ever exercised. If you later discover a concrete structure, narrow it (e.g. `{ source: string; [k: string]: unknown }`).
- **`last_login`** stays `string` rather than `Date` to preserve the wire format; parse at the boundary if you need a `Date`.
- The validator uses an `asserts user is User` signature so callers get compile-time narrowing after the call, mirroring how the Python `assert` block gates downstream access.

