#!/usr/bin/env python3
"""Count log levels (INFO, WARN, ERROR, DEBUG) per .log file in a directory."""

import argparse
import os
import re
import sys


def count_log_levels(filepath):
    """Return dict of level counts for one log file."""
    patterns = {
        "INFO":  re.compile(r"\bINFO\b"),
        "WARN":  re.compile(r"\bWARN(?:ING)?\b"),
        "ERROR": re.compile(r"\bERROR\b"),
        "DEBUG": re.compile(r"\bDEBUG\b"),
    }
    counts = {k: 0 for k in patterns}

    try:
        with open(filepath, "r", encoding="utf-8", errors="replace") as fh:
            for line in fh:
                for level, pat in patterns.items():
                    if pat.search(line):
                        counts[level] += 1
    except OSError as exc:
        print(f"warning: skipping {filepath}: {exc}", file=sys.stderr)

    return counts


def build_table(results):
    """Return a list of formatted table lines (header, separator, rows)."""
    headers = ["FILE", "INFO", "WARN", "ERROR", "DEBUG"]
    rows = [
        [name, str(c["INFO"]), str(c["WARN"]), str(c["ERROR"]), str(c["DEBUG"])]
        for name, c in results
    ]

    # Column widths: max of header and all cells in that column.
    widths = []
    for i in range(5):
        col_max = len(headers[i])
        for row in rows:
            col_max = max(col_max, len(row[i]))
        widths.append(col_max)

    def fmt_row(cells, align_right_from=1):
        parts = []
        for i, cell in enumerate(cells):
            if i >= align_right_from:
                parts.append(cell.rjust(widths[i]))
            else:
                parts.append(cell.ljust(widths[i]))
        return "  ".join(parts)

    lines = [fmt_row(headers)]
    lines.append("  ".join("-" * w for w in widths))
    for row in rows:
        lines.append(fmt_row(row))
    return lines


def main():
    parser = argparse.ArgumentParser(
        description="Summarise log-level counts across .log files."
    )
    parser.add_argument("directory", help="Path to directory containing .log files")
    parser.add_argument(
        "--min-errors", type=int, default=0, metavar="N",
        help="Only display files with >= N ERROR lines (default: 0)",
    )
    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print(f"error: '{args.directory}' is not a directory.", file=sys.stderr)
        sys.exit(1)

    log_files = sorted(
        f for f in os.listdir(args.directory)
        if f.endswith(".log") and os.path.isfile(os.path.join(args.directory, f))
    )

    if not log_files:
        print("No .log files found.", file=sys.stderr)
        sys.exit(0)

    results = []
    for fname in log_files:
        counts = count_log_levels(os.path.join(args.directory, fname))
        if counts["ERROR"] >= args.min_errors:
            results.append((fname, counts))

    if not results:
        print(f"No files meet the --min-errors {args.min_errors} threshold.",
              file=sys.stderr)
        sys.exit(0)

    for line in build_table(results):
        print(line)


if __name__ == "__main__":
    main()
```

**Usage:**

```bash
python logcount.py /var/log/myapp/
python logcount.py ./logs --min-errors 5
```

**How it works:**

- Scans the given directory for files ending in `.log` (non-recursive, sorted by name).
- For each file, applies four word-boundary regexes per line. `WARN` also matches `WARNING`. A single line can increment more than one counter if it contains multiple level tokens (rare but handled correctly).
- Prints an aligned table; numeric columns are right-aligned, the filename column left-aligned.
- `--min-errors N` filters rows *after* counting, so you still get accurate totals for files that pass the threshold. Default `0` shows everything.
- Unreadable files produce a warning on stderr and are skipped (counted as zeros).
